ck('DWORD40 advance and captured-end compares',[(i.address,i.mnemonic,i.op_str) for i in ins if i.address in (0xab57ea,0xab57f7,0xab57fa)]==[(0xab57ea,'cmp','esi, edi'),(0xab57f7,'add','esi, 0x40'),(0xab57fa,'cmp','esi, edi')])
