ck('Native unused selfmov is preserved as no data effect and RET8 ABI excluded',any(i.address==0xab57ee and i.mnemonic=='mov' and i.op_str=='edi, edi' for i in ins) and bytes(ins[-1].bytes)==bytes.fromhex('c20800'))
h=read(r['owned_paths'][0]).decode();c=read(r['owned_paths'][1]).decode();clean=re.sub(r'//[^\n]*','',c)
ck('two actual volatile homes and genuine existing context','const volatile std::uint32_t (&actual_argument_homes)[2]' in h and 'NativeGuiIconStorageContext& context' in h)
ck('exact capture order once and no home mutation',re.findall(r'actual_argument_homes\[([^]]+)\]',clean)==['0','1'] and c.index('current = actual_argument_homes[0];')<c.index('end = actual_argument_homes[1];'))
ck('only equality loop, no added input/feature/domain condition',re.findall(r'\bwhile\s*\(([^)]*)\)',clean)==['current != end'] and re.search(r'\bif\s*\(',clean) is None)
