ck('ordinary void interface has no Native incidental return receipt','void destroy_native_gui_icon_state_range_storage_00ab57e0(' in h and 'return ' not in clean)
ck('inherited callee policy and Source lifetime qualifiers explicit',all(x in h for x in ['terminates on a secondary failure','wrapper adds no catch','Retain all lifetimes','Source control/spill storage']))
ck('no Native exception-origin/ABI/runtime credit',r['Original_ABI_Origin_runtime_activation'] is False and r['new_Original_vendor_helper_CG_duplicate_credit']==0)

def tree(rev):
    out={}
    for raw in g('ls-tree','-r','-z',rev).split(b'\0'):
        if raw:
            m,p=raw.split(b'\t',1);mode,kind,oid=m.decode().split();out[p.decode()]=(mode,kind,oid)
    return out
def treehash(items):
    root={}
    for p,v in items.items():
        n=root;parts=p.split('/')
        for s in parts[:-1]:n=n.setdefault(s,{})
