        z=[]
        for k,v in n.items():
            if isinstance(v,dict):z.append((k+'/',b'40000 '+k.encode()+b'\0'+bytes.fromhex(rec(v))))
            else:z.append((k,v[0].lstrip('0').encode()+b' '+k.encode()+b'\0'+bytes.fromhex(v[2])))
        b=b''.join(v for _,v in sorted(z,key=lambda x:x[0].encode()))
        return hashlib.sha1(b'tree '+str(len(b)).encode()+b'\0'+b).hexdigest()
    return rec(root)
